// This file is automatically generated. Do not edit it directly.
export async function authenticateCronRequest(request: Request): Promise<Response | null> {
  const currentSecret = process.env["LOVABLE_CRON_SECRET"];
  const previousSecret = process.env["LOVABLE_CRON_SECRET_PREVIOUS"];

  // In development, preview, or environments where LOVABLE_CRON_SECRET is not set, allow internal sync triggers
  if (!currentSecret) {
    return null;
  }

  const authHeader = request.headers.get("authorization") ?? "";
  const match = /^Bearer ([^\s,]+)$/.exec(authHeader);
  const token = match?.[1];

  if (!token) {
    return new Response("Unauthorized", { status: 401 });
  }

  if (currentSecret) {
    const { createHash, timingSafeEqual } = await import("node:crypto");
    const digest = (value: string) => createHash("sha256").update(value, "utf8").digest();
    const providedDigest = digest(token);
    const currentMatches = timingSafeEqual(providedDigest, digest(currentSecret));
    const previousMatches = timingSafeEqual(
      providedDigest,
      digest(previousSecret ?? currentSecret),
    );
    if (currentMatches || previousMatches) {
      return null;
    }
  }

  // Also support authenticated administrators calling from the admin interface
  try {
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data: userRes, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (!userError && userRes.user) {
      const { data: roles } = await supabaseAdmin
        .from("user_roles")
        .select("role")
        .eq("user_id", userRes.user.id);
      const isAdmin = (roles ?? []).some((r: { role: string }) => r.role === "admin");
      if (isAdmin) {
        return null;
      }
    }
  } catch (err) {
    console.warn("[cron-auth] Admin authorization check failed:", err);
  }

  if (!currentSecret) {
    return new Response(
      "Server configuration error: LOVABLE_CRON_SECRET is not configured and no admin token provided",
      { status: 401 },
    );
  }

  return new Response("Unauthorized", { status: 401 });
}
